[] a sh:ValidationReport ;
    sh:conforms false ;
    sh:result [ a sh:ValidationResult ;
            sh:focusNode [ a time:ProperInterval ;
                    schema1:description "nde:temporalType: collection" ;
                    time:hasBeginning [ a time:Instant ;
                            time:inXSDDate "15 July 2008" ] ;
                    time:hasEnd [ a time:Instant ;
                            time:inXSDDate "2011-07-15" ] ] ;
            sh:resultMessage "A time interval beginning must be typed time:Instant and give either a time:inTimePosition that is a time:TimePosition, or a time:inXSDDate (YYYY-MM-DD)" ;
            sh:resultPath time:hasBeginning ;
            sh:resultSeverity sh:Violation ;
            sh:sourceConstraintComponent sh:OrConstraintComponent ;
            sh:sourceShape [ sh:message "A time interval beginning must be typed time:Instant and give either a time:inTimePosition that is a time:TimePosition, or a time:inXSDDate (YYYY-MM-DD)" ;
                    sh:or ( cdifd:numericInstantShape cdifd:calendarInstantShape ) ;
                    sh:path time:hasBeginning ] ;
            sh:value [ a time:Instant ;
                    time:inXSDDate "15 July 2008" ] ] .

